import numpy as np
from scipy.spatial.transform import Rotation as R
from scipy.optimize import least_squares

def trans(x=0,y=0,z=0):
 t=np.eye(4);t[:3,3]=[x,y,z];return t

def rot(axis,a):
 t=np.eye(4);t[:3,:3]=R.from_rotvec(np.array(axis)*a).as_matrix();return t

origins=[trans(z=.333),rot([1,0,0],-np.pi/2),trans(y=-.316)@rot([1,0,0],np.pi/2),trans(x=.0825)@rot([1,0,0],np.pi/2),trans(x=-.0825,y=.384)@rot([1,0,0],-np.pi/2),rot([1,0,0],np.pi/2),trans(x=.088)@rot([1,0,0],np.pi/2)]

def fk(q,tip=.2104):
 t=trans(y=-.4,z=.78)@rot([0,0,1],np.pi/2)
 for o,a in zip(origins,q):t=t@o@rot([0,0,1],a)
 return t@trans(z=tip)@rot([0,0,1],-np.pi/4)

